/* Program-side configuration ABI v1. No libc/kernel headers required. */
#ifndef LS_CONFIG_BPF_H
#define LS_CONFIG_BPF_H
typedef unsigned int ls_cfg_u32;
typedef unsigned long long ls_cfg_u64;
struct ls_cfg_meta {
    ls_cfg_u64 revision, instance;
    ls_cfg_u32 schema, entries;
    ls_cfg_u64 reserved;
};
struct ls_cfg_map_def {
    ls_cfg_u32 type, key_size, value_size, max_entries, map_flags;
};
/* A dedicated ARRAY view; does not occupy the legacy four-map registry.
 * Keep the ELF symbol GLOBAL: with static/local symbols clang relocates via the
 * section, and pinned PREVAIL refuses the helper argument as not a map_fd. */
struct ls_cfg_map_def ls_config_v1 __attribute__((section("maps"), used)) = {
    2, 4, 32, 17, 128
};
static void *(*ls_cfg_lookup_helper)(void *, const void *) = (void *)1;
static __attribute__((always_inline)) inline void *ls_cfg_get(ls_cfg_u32 index)
{
    return ls_cfg_lookup_helper(&ls_config_v1, &index);
}
#endif

ls_config.h.text:
/* ls_config.h -- bounded controller input, independent of mutable hash maps.
 * Single serialized control writer; readers make ONE attempt, never spin.
 * Atomic payload words are essential: a seqlock around ordinary memcpy would
 * still be a C data race. Sequential consistency gives the copy/check protocol
 * one total order. This is deliberately conservative until measured on TMM.
 */
#ifndef LS_CONFIG_H
#define LS_CONFIG_H
#include <stdatomic.h>
#include <stdint.h>
#include <stddef.h>
#include <string.h>
#if __BYTE_ORDER__ != __ORDER_LITTLE_ENDIAN__
#error "configuration wire ABI v1 requires a little-endian host"
#endif

#define LS_CONFIG_ABI 1u
#define LS_CONFIG_SLOTS 64u
#define LS_CONFIG_ROWS 16u
#define LS_CONFIG_VALUE_SIZE 32u
#define LS_CONFIG_MAP_NAME "ls_config_v1"
#define LS_CONFIG_MAP_FLAG 128u /* BPF_F_RDONLY_PROG; host image never exposed */
#define LS_CONFIG_HANDLE_BIT (UINT64_C(1) << 63)

struct ls_config_meta {
    uint64_t revision;
    uint64_t instance;
    uint32_t schema;
    uint32_t entries;
    uint64_t reserved;
};
struct ls_config_image {
    struct ls_config_meta meta; /* array index 0; data occupy indices 1..entries */
    uint8_t rows[LS_CONFIG_ROWS][LS_CONFIG_VALUE_SIZE];
};
#define LS_CONFIG_WORDS (sizeof(struct ls_config_image) / sizeof(uint64_t))
_Static_assert(sizeof(struct ls_config_meta) == 32, "config metadata ABI");
_Static_assert(sizeof(struct ls_config_image) == 544, "config image ABI");
_Static_assert(ATOMIC_LLONG_LOCK_FREE == 2, "config requires lock-free 64-bit atomics");

/* Little-endian wire body in shield_msg.prog, CONFIG_PUBLISH only. */
struct ls_config_request {
    uint32_t abi, schema;
    uint64_t session, instance, expected_revision, revision;
    uint32_t entries, reserved;
    uint8_t program_sha256[32];
    uint8_t rows[LS_CONFIG_ROWS][LS_CONFIG_VALUE_SIZE];
};
#define LS_CONFIG_REQUEST_HEADER 80u
_Static_assert(offsetof(struct ls_config_request, rows) == LS_CONFIG_REQUEST_HEADER,
               "config request ABI");

struct ls_config_slot {
    _Atomic uint64_t sequence;
    _Atomic uint64_t words[LS_CONFIG_WORDS];
    /* Control-plane only. Never read by a program or a data-path thread. */
    struct ls_config_meta current;
    uint8_t program_sha256[32];
};
struct ls_config_store {
    uint64_t session, next_instance; /* serialized load/publish control path */
    uint64_t loading;               /* relocation cookie for VM being prepared */
    int load_error;
    struct ls_config_slot slots[LS_CONFIG_SLOTS];
};
struct ls_config_view {
    int active, attempted, available;
    unsigned slot;
    uint64_t handle;
    struct ls_config_image image; /* program-writable, invocation-private copy */
};

static inline uint64_t
ls_config_new_instance(struct ls_config_store *s, unsigned slot)
{
    if (slot >= LS_CONFIG_SLOTS || s->next_instance >= (LS_CONFIG_HANDLE_BIT >> 6) - 1)
        return 0;
    return LS_CONFIG_HANDLE_BIT | (++s->next_instance << 6) | slot;
}

static inline int
ls_config_write(struct ls_config_slot *s, const struct ls_config_image *image)
{
    uint64_t seq = atomic_load(&s->sequence);
    if ((seq & 1) || seq > UINT64_MAX - 2)
        return -1;
    atomic_store(&s->sequence, seq + 1);
    for (size_t i = 0; i < LS_CONFIG_WORDS; i++) {
        uint64_t word;
        memcpy(&word, (const uint8_t *)image + i * 8, 8);
        atomic_store(&s->words[i], word);
    }
    atomic_store(&s->sequence, seq + 2);
    s->current = image->meta;
    return 0;
}

/* Called after successful load; token was embedded in that VM's map relocation.
 * In-flight old bytecode retains its old token, so cannot read the new image. */
static inline int
ls_config_bind(struct ls_config_store *s, unsigned slot, uint64_t instance,
               const uint8_t sha[32])
{
    struct ls_config_image empty = {0};
    if (slot >= LS_CONFIG_SLOTS || !(instance & LS_CONFIG_HANDLE_BIT) ||
        (instance & 63) != slot)
        return -1;
    empty.meta.instance = instance;
    if (ls_config_write(&s->slots[slot], &empty) != 0)
        return -1;
    memcpy(s->slots[slot].program_sha256, sha, 32);
    return 0;
}

static inline int
ls_config_revoke(struct ls_config_store *s, unsigned slot)
{
    struct ls_config_image empty = {0};
    if (slot >= LS_CONFIG_SLOTS)
        return -1;
    return ls_config_write(&s->slots[slot], &empty);
}

/* NULL means published. Errors never modify the previous image. A zero-row
 * publication is an explicit empty configuration, not a reset of revision. */
static inline const char *
ls_config_publish(struct ls_config_store *s, unsigned slot, const void *body, size_t len)
{
    struct ls_config_request r = {0};
    struct ls_config_image image = {0};
    if (slot >= LS_CONFIG_SLOTS || !body || len < LS_CONFIG_REQUEST_HEADER || len > sizeof r)
        return "config length or slot";
    memcpy(&r, body, len);
    if (r.abi != LS_CONFIG_ABI || r.reserved || !r.schema || r.entries > LS_CONFIG_ROWS ||
        len != LS_CONFIG_REQUEST_HEADER + r.entries * LS_CONFIG_VALUE_SIZE)
        return "config ABI, schema, reserved, or shape";
    struct ls_config_slot *dst = &s->slots[slot];
    if (!s->session || r.session != s->session)
        return "config session mismatch";
    if (!dst->current.instance || r.instance != dst->current.instance ||
        memcmp(r.program_sha256, dst->program_sha256, 32))
        return "config program instance/hash mismatch";
    if (r.expected_revision != dst->current.revision || r.revision <= r.expected_revision)
        return "config revision conflict";
    image.meta.instance = r.instance;
    image.meta.revision = r.revision;
    image.meta.schema = r.schema;
    image.meta.entries = r.entries;
    memcpy(image.rows, r.rows, r.entries * LS_CONFIG_VALUE_SIZE);
    return ls_config_write(dst, &image) == 0 ? NULL : "config sequence exhausted";
}

static inline void
ls_config_begin(struct ls_config_view *v, unsigned slot)
{
    v->active = 1;
    v->slot = slot;
    v->attempted = v->available = 0;
    v->handle = 0;
}

static inline void *
ls_config_lookup(struct ls_config_store *s, struct ls_config_view *v,
                 uint64_t handle, uint32_t key)
{
    if (!v->active || !(handle & LS_CONFIG_HANDLE_BIT) ||
        v->slot >= LS_CONFIG_SLOTS || (handle & 63) != v->slot || key > LS_CONFIG_ROWS)
        return NULL;
    if (!v->attempted) {
        v->attempted = 1;
        v->handle = handle;
        struct ls_config_slot *src = &s->slots[v->slot];
        uint64_t before = atomic_load(&src->sequence);
        if (before & 1)
            return NULL;
        for (size_t i = 0; i < LS_CONFIG_WORDS; i++) {
            uint64_t word = atomic_load(&src->words[i]);
            memcpy((uint8_t *)&v->image + i * 8, &word, 8);
        }
        if (before != atomic_load(&src->sequence) || v->image.meta.instance != handle ||
            !v->image.meta.revision)
            return NULL;
        v->available = 1;
    }
    if (!v->available || handle != v->handle || key > v->image.meta.entries)
        return NULL;
    return (uint8_t *)&v->image + key * LS_CONFIG_VALUE_SIZE;
}

static inline int
ls_config_addr_ok(const struct ls_config_view *v, uint64_t addr, uint64_t size)
{
    uint64_t base = (uint64_t)(uintptr_t)&v->image;
    /* Use the fixed allocation bound, not program-writable metadata. */
    return v->active && v->available && addr >= base && addr - base < sizeof v->image &&
           size <= LS_CONFIG_VALUE_SIZE - ((addr - base) % LS_CONFIG_VALUE_SIZE);
}
#endif

ls_map.h.text:
/* ls_map.h --- state that survives between program invocations.
 *
 * WHY THIS IS THE UNLOCK. Until now a program saw one invocation, answered yes or
 * no, and forgot everything. The only question expressible was "is this one input
 * bad?". With a map it can ask "has this client done this forty times in a
 * minute?" --- which is what most real abuse looks like, and what TMM's tmstat
 * counters cannot answer because they hold totals with no link back to the
 * request that caused them.
 *
 * THREE THINGS THAT MADE THIS CHEAPER THAN EXPECTED, each an assumption that was
 * wrong:
 *
 *   - PREVAIL already understands maps. A program declaring a standard
 *     SEC("maps") hash and calling helpers 1/2/3 verifies UNCHANGED, with every
 *     gate on (substrate/shields/exp/map_probe.bpf.c). Helper ids 1/2/3 are the
 *     standard BPF map helpers and PREVAIL's linux platform knows their
 *     signatures, so implementing those ids with those semantics needs no
 *     verifier work at all.
 *   - uBPF resolves the map reference for us. clang emits `lddw r1, 0` plus an
 *     R_BPF_64_64 relocation against the map symbol, and uBPF ignores
 *     relocations --- so the helper would receive 0. But
 *     ubpf_register_data_relocation() is a callback for exactly this: uBPF hands
 *     us the maps section and the symbol offset, and we return the value to plant
 *     in the instruction.
 *   - uBPF can be taught that map memory is legal. Its bounds check permits only
 *     the ctx and the stack, so a returned value pointer would be refused;
 *     ubpf_register_data_bounds_check() extends that. Note the JIT does NOT
 *     bounds-check at all, so without this the interpreter and the JIT would
 *     disagree --- working in production and failing in test, which is the worst
 *     possible split.
 *
 * WHAT THE PROGRAM IS HANDED, AND THE SECURITY BOUNDARY. The relocation returns
 * a SMALL INDEX, not a pointer. So a program never holds or supplies a host
 * address, and validating a map reference is a range check on an integer --- there
 * is no forged-pointer case to defend against. That is stronger than real BPF's
 * arrangement and it fell out of uBPF's missing relocation step.
 *
 * PREVAIL proves the program passed *a map descriptor* and that it reads at most
 * value_size bytes of what lookup returned. It cannot prove the HOST resolves the
 * index to a map of that shape. So ls_map_check_descriptor() is the crossing
 * where the verifier's assumption meets our storage, and it is the same class of
 * check as finding O14: the verifier proved something about one artifact and the
 * runtime must be shown to agree.
 *
 * PER THREAD, FIXED SIZE, NO LOCKS. One map set per TMM thread, mmap'd at init,
 * never grown, never rehashed. Per-thread removes locking from the hot path by
 * construction, which is the same reason the egress ring is per-thread. mmap
 * rather than malloc because TMM aliases malloc to a per-core allocator whose
 * spinlock is never initialised on threads TMM did not create.
 *
 * Collision policy is EVICT, counted. A bounded table that blocks or fails on a
 * full bucket would put an attacker in control of the data path; overwriting the
 * incumbent and counting it keeps the cost fixed and the loss visible.
 */
#ifndef LS_MAP_H
#define LS_MAP_H

#include <stdint.h>
#include <string.h>

#define LS_MAP_MAX      4u      /* maps per program                     */
#define LS_MAP_ENTRIES  256u    /* power of two --- index masks cleanly  */
#define LS_MAP_KEY_MAX  16u
#define LS_MAP_VAL_MAX  32u

/* Matches struct bpf_map_def, which is what clang writes into SEC("maps") and
 * what PREVAIL parses. Read by the relocation callback. */
struct ls_map_def {
    uint32_t type, key_size, value_size, max_entries, map_flags;
};

#define LS_MAP_TYPE_HASH 1u     /* BPF_MAP_TYPE_HASH */
/*
 * BPF_MAP_TYPE_RINGBUF, and it is NOT storage --- it is a handle on the thread's
 * existing egress ring.
 *
 * WHY A MAP AT ALL. bpf_ringbuf_output(rb, data, size, flags) is helper id 130, whose
 * first argument is a map reference, and PREVAIL already knows that signature --- so a
 * program can emit with ZERO verifier work. Verified 2026-08-18: a program declaring a
 * SEC("maps") entry of this type and calling id 130 passes PREVAIL unchanged. Inventing
 * our own emit helper at a private id would have meant teaching PREVAIL about it.
 *
 * A ringbuf descriptor is SHAPED DIFFERENTLY from a hash one: key_size and value_size
 * are both 0 and max_entries is a BYTE COUNT. So ls_map_check_descriptor has to admit a
 * shape it otherwise (correctly) refuses, and ls_map_create must not allocate a table
 * for it.
 */
#define LS_MAP_TYPE_RINGBUF 27u /* BPF_MAP_TYPE_RINGBUF --- the egress ring     */
/*
 * AND THE ONE ACTUALLY USED, found the hard way. bpf_ringbuf_output is helper id 130, and
 * uBPF's external-function table is UBPF_MAX_EXT_FUNCS entries --- 64 by default
 * (ubpf.h:72). So ubpf_register(vm, 130, ...) returns -1, the all-or-nothing install
 * failed, and an image shipped in which NO helper registered at all: every program load
 * was refused and even the built-in shield never armed. Loud, which is what
 * all-or-nothing is for.
 *
 * bpf_perf_event_output is id 25 --- inside the table --- and PREVAIL knows it just as
 * well (verified: a program declaring this map type and calling id 25 passes unchanged).
 * Its descriptor is shaped like a HASH one (key_size 4, value_size 4), so type is the only
 * thing that separates them, which is why the check below switches on d->type.
 */
#define LS_MAP_TYPE_PERF_EVENT_ARRAY 4u /* BPF_MAP_TYPE_PERF_EVENT_ARRAY        */

struct ls_map {
    uint32_t in_use;
    /* A ringbuf slot holds NO storage: keys/vals stay zeroed and every hash operation
     * on it must refuse. Kept in the same array as the hash maps because the program
     * refers to both by the same index space, and splitting them would mean two
     * relocation namespaces for no gain. */
    uint32_t is_ring;
    uint32_t key_sz, val_sz, entries;
    uint64_t hits, misses, evictions, updates;
    uint8_t  used[LS_MAP_ENTRIES];
    uint8_t  keys[LS_MAP_ENTRIES * LS_MAP_KEY_MAX];
    uint8_t  vals[LS_MAP_ENTRIES * LS_MAP_VAL_MAX];
};

struct ls_map_set {
    struct ls_map m[LS_MAP_MAX];
    uint32_t      n;
    uint64_t      generation;
};

/* FNV-1a over the key bytes. Not cryptographic and does not need to be: the
 * table is per-thread and bounded, so the worst an attacker achieves by forcing
 * collisions is eviction of their own entries, which is already the policy. */
static inline uint32_t
ls_map_hash(const uint8_t *k, uint32_t n)
{
    uint32_t h = 2166136261u, i;
    for (i = 0; i < n; i++) {
        h ^= k[i];
        h *= 16777619u;
    }
    return h & (LS_MAP_ENTRIES - 1u);
}

/*
 * THE CROSSING. PREVAIL verified the program against the descriptor in the ELF;
 * this is where that descriptor is checked against what the host can actually
 * store. A mismatch means the verifier proved bounds for a shape we do not
 * enforce, so it is a REFUSAL, never a clamp.
 */
static inline int
ls_map_check_descriptor(const struct ls_map_def *d)
{
    /* The ringbuf shape, checked FIRST and on its own terms. key_size and value_size
     * are 0 by definition here, so falling through to the hash checks below would
     * refuse it --- and refusing it is right for a hash map and wrong for this. */
    if (d->type == LS_MAP_TYPE_RINGBUF) {
        if (d->key_size != 0 || d->value_size != 0)  return 0;
        if (d->max_entries == 0)                     return 0;
        return 1;
    }
    /* A perf-event array is shaped like a hash map (4/4), so ONLY the type
     * separates them. Admitted on its own terms and never given storage. */
    if (d->type == LS_MAP_TYPE_PERF_EVENT_ARRAY) {
        if (d->max_entries == 0)                     return 0;
        return 1;
    }
    if (d->type != LS_MAP_TYPE_HASH)                return 0;
    if (d->key_size == 0 || d->key_size > LS_MAP_KEY_MAX)   return 0;
    if (d->value_size == 0 || d->value_size > LS_MAP_VAL_MAX) return 0;
    if (d->max_entries == 0 || d->max_entries > LS_MAP_ENTRIES) return 0;
    return 1;
}

/* Create a map from a verified descriptor. Returns its index, or -1. */
static inline int
ls_map_create(struct ls_map_set *s, const struct ls_map_def *d)
{
    struct ls_map *m;
    if (s->n >= LS_MAP_MAX || !ls_map_check_descriptor(d))
        return -1;
    m = &s->m[s->n];
    memset(m, 0, sizeof *m);
    m->in_use  = 1;
    if (d->type == LS_MAP_TYPE_RINGBUF ||
        d->type == LS_MAP_TYPE_PERF_EVENT_ARRAY) {
        /* No table. The slot exists only so an index resolves to "the egress ring";
         * key_sz and val_sz stay 0, which is what every hash operation checks against
         * before touching storage. */
        m->is_ring = 1;
        return (int)s->n++;
    }
    m->key_sz  = d->key_size;
    m->val_sz  = d->value_size;
    m->entries = d->max_entries;
    return (int)s->n++;
}

/* Resolve an index handed back by a program. THE validation --- an integer range
 * check, because the program never holds an address. */
static inline struct ls_map *
ls_map_get(struct ls_map_set *s, uint64_t idx)
{
    if (s == 0)
        return 0;           /* helper ran on a thread with no maps --- fail safe */
    if ((idx >> 8) != s->generation)
        return 0;           /* reference from a retired registry generation */
    idx &= 255u;
    if (idx >= LS_MAP_MAX || idx >= (uint64_t)s->n)
        return 0;
    return s->m[idx].in_use ? &s->m[idx] : 0;
}

/* Linear probe from the hash, bounded by the table size --- so a lookup is O(1)
 * with a constant worst case, which is what a data path requires. */
static inline int
ls_map_slot(struct ls_map *m, const uint8_t *key, int for_insert)
{
    uint32_t h = ls_map_hash(key, m->key_sz) % m->entries, i, s;
    int empty = -1;
    for (i = 0; i < m->entries; i++) {
        s = (h + i) % m->entries;
        if (!m->used[s]) {
            if (empty < 0) empty = (int)s;
            continue;
        }
        if (memcmp(&m->keys[s * LS_MAP_KEY_MAX], key, m->key_sz) == 0)
            return (int)s;
    }
    /* Deletion leaves holes. Search the whole bounded table before inserting,
     * or an existing colliding key beyond a hole can be duplicated or missed. */
    if (for_insert && empty >= 0)
        return empty;
    /* Full: evict at the hash position rather than failing. Counted by the
     * caller --- a silent eviction is indistinguishable from a miss. */
    return for_insert ? (int)h : -1;
}

static inline void *
ls_map_lookup(struct ls_map *m, const uint8_t *key)
{
    /* A RINGBUF slot has no table. Refusing here rather than relying on key_sz==0
     * arithmetic further down: a hash operation on the ring must be an explicit
     * no-op, not an accident of zero sizes. */
    if (m != 0 && m->is_ring)
        return 0;

    int s = ls_map_slot(m, key, 0);
    if (s < 0) { m->misses++; return 0; }
    m->hits++;
    return &m->vals[(uint32_t)s * LS_MAP_VAL_MAX];
}

static inline int
ls_map_update(struct ls_map *m, const uint8_t *key, const uint8_t *val)
{
    /* A RINGBUF slot has no table. Refusing here rather than relying on key_sz==0
     * arithmetic further down: a hash operation on the ring must be an explicit
     * no-op, not an accident of zero sizes. */
    if (m != 0 && m->is_ring)
        return -1;

    int s = ls_map_slot(m, key, 1);
    if (s < 0)
        return -1;
    if (m->used[s] && memcmp(&m->keys[(uint32_t)s * LS_MAP_KEY_MAX], key, m->key_sz) != 0)
        m->evictions++;
    memcpy(&m->keys[(uint32_t)s * LS_MAP_KEY_MAX], key, m->key_sz);
    memcpy(&m->vals[(uint32_t)s * LS_MAP_VAL_MAX], val, m->val_sz);
    m->used[s] = 1;
    m->updates++;
    return 0;
}

static inline int
ls_map_delete(struct ls_map *m, const uint8_t *key)
{
    /* A RINGBUF slot has no table. Refusing here rather than relying on key_sz==0
     * arithmetic further down: a hash operation on the ring must be an explicit
     * no-op, not an accident of zero sizes. */
    if (m != 0 && m->is_ring)
        return -1;

    int s = ls_map_slot(m, key, 0);
    if (s < 0)
        return -1;
    m->used[s] = 0;
    return 0;
}

/*
 * The bounds-check callback's predicate: is `addr` inside a value slot of some
 * map in this set, for `size` bytes?
 *
 * Deliberately checks against the VALUE array only. Keys and metadata are the
 * host's; a program has no business reading either, and PREVAIL never gives it a
 * pointer to them.
 */
static inline int
ls_map_addr_ok(struct ls_map_set *s, uint64_t addr, uint64_t size)
{
    uint32_t i;
    for (i = 0; i < s->n; i++) {
        struct ls_map *m = &s->m[i];
        uint64_t lo = (uint64_t)(uintptr_t)m->vals;
        uint64_t hi = lo + (uint64_t)m->entries * LS_MAP_VAL_MAX;
        if (addr < lo || addr >= hi)
            continue;
        /* Must not straddle the end of the slot it starts in --- otherwise a
         * program could read one value and the beginning of the next. */
        if (size > LS_MAP_VAL_MAX)
            return 0;
        if (((addr - lo) % LS_MAP_VAL_MAX) + size > LS_MAP_VAL_MAX)
            return 0;
        if (addr + size > hi)
            return 0;
        return 1;
    }
    return 0;
}

#endif /* LS_MAP_H */

ls_map_glue.h.text:
/* ls_map_glue.h --- the three uBPF callbacks that make maps work.
 *
 * Registered on every VM before the ELF is loaded, because the relocation
 * callback has to be in place when uBPF walks the maps section.
 *
 *   relocation    resolve `lddw r1, <map symbol>` to a map INDEX
 *   bounds check  permit reads of map VALUE memory
 *   helpers 1/2/3 the standard BPF map helpers, which PREVAIL already knows
 *
 * ALL FIVE REGISTRATIONS GO THROUGH ls_map_glue_install(), AND THAT IS THE POINT.
 * On 2026-08-17 the registration calls existed only in the build box's copy of
 * ls_vm.c and were never carried back here; copying this tree over that one
 * deleted them. Every symptom pointed elsewhere. The programs still loaded, still
 * ran, still verified --- their maps were simply always empty, which is
 * indistinguishable from a predicate that never matches. What caught it was the
 * build's globals manifest: with nothing calling ls_map_reloc, the compiler
 * removed g_ls_shapes as dead, and the manifest noticed a name it expected was
 * gone. A five-call sequence spread across two arm paths is a sequence that can
 * be half-applied; one function cannot.
 *
 * ORDER MATTERS AND IS EASY TO GET WRONG. ubpf_register_data_relocation must
 * precede ubpf_load_elf_ex; registered after, the maps section has already been
 * walked and every `lddw` still holds the zero clang emitted. The program then
 * runs, calls a helper with map=0, gets NULL, and behaves like a map that is
 * simply always empty --- which looks like a working feature and is not.
 */
#ifndef LS_MAP_GLUE_H
#define LS_MAP_GLUE_H

#include "ls_map.h"
#include <stdatomic.h>
#include <stdio.h>
#include <sys/mman.h>
#include "ls_tp.h"
#include "ubpf.h"
#include <fcntl.h>
#include <stdlib.h>   /* strtoull, for the /proc/self/maps parse */
#include <time.h>
#include <unistd.h>

/*
 * SHAPE IS GLOBAL, STORAGE IS PER THREAD, and the split is forced rather than
 * chosen. g_slots in ls_vm.c is a plain process-global, so one VM is shared by
 * every TMM thread --- but relocation runs ONCE, on the loader thread, when the
 * ELF is loaded. If the map set were purely thread-local, the loader thread would
 * get the maps and every data-plane thread would find none: lookups return NULL
 * forever and the feature looks like a map that is always empty.
 *
 * So relocation records only the SHAPE in a process-global table, and each thread
 * allocates its own STORAGE from those shapes the first time a helper runs on it.
 * Threads never share a table. VM calls use an atomic reader count to prevent
 * registry reset during execution; they do not wait for a reset.
 */
/* ONE TU DEFINES THESE, EVERY OTHER TU SEES EXTERNS. They were `static`, which
 * in a header means each including TU gets its OWN copy --- the shapes written by
 * relocation would be invisible to a helper compiled elsewhere. That never bit us
 * only because exactly one file happened to include this header; the install
 * function below means two now do. The owner defines LS_MAP_GLUE_IMPL before
 * including (ls_vm_load.c). If a second file ever does, the link fails on a
 * duplicate symbol --- loudly, at build time, which is the whole reason to prefer
 * extern here over a comment asking people to be careful. */
/*
 * IDENTITY IS THE SYMBOL NAME, NOT THE SHAPE --- and that is a fix, not a
 * preference. This table used to dedup on (key_size, value_size, max_entries)
 * alone, which is correct WITHIN one program (clang emits one relocation per
 * reference, so the same map arrives several times) and wrong ACROSS programs,
 * because g_ls_shapes is process-global and never scoped by slot. Two unrelated
 * programs each declaring a 4-byte-key/8-byte-value/64-entry map resolved to the
 * SAME index and therefore the same per-thread storage: each saw the other's
 * counts as its own. Nothing reported it --- shared state looks exactly like a
 * program whose counters are running a little high.
 *
 * Keying on the name makes both behaviours explicit and separates them:
 *
 *   same name, same shape        -> SHARE the index. Deliberate, and it is what
 *                                   lets a timer program read the counters an
 *                                   entry-armed program is accumulating.
 *   same name, different shape   -> REFUSE. Two programs disagreeing about a
 *                                   shared map's layout is the one case where
 *                                   sharing corrupts, so it must not resolve.
 *   different name               -> a NEW index, i.e. private storage.
 *
 * uBPF already hands us symbol_name; the old code took it only to print it.
 */
#define LS_MAP_NAME_MAX 32u

/* Registry reset is off the data path and never waits for a reader. References
 * carry a generation, so a retained VM cannot alias a replacement's maps. */
struct ls_map_registry {
    _Atomic uint64_t generation;
    _Atomic uint32_t readers, resetting;
};
#ifdef LS_MAP_GLUE_IMPL
struct ls_map_registry g_ls_map_registry;
#else
extern struct ls_map_registry g_ls_map_registry;
#endif

static inline int
ls_map_enter(void)
{
    atomic_fetch_add(&g_ls_map_registry.readers, 1);
    if (atomic_load(&g_ls_map_registry.resetting)) {
        atomic_fetch_sub(&g_ls_map_registry.readers, 1);
        return -1;
    }
    return 0;
}

static inline void
ls_map_leave(void)
{
    atomic_fetch_sub(&g_ls_map_registry.readers, 1);
}

#include "ls_config.h"
#ifdef LS_MAP_GLUE_IMPL
struct ls_config_store g_ls_config;
__thread struct ls_config_view g_ls_config_view;
#else
extern struct ls_config_store g_ls_config;
extern __thread struct ls_config_view g_ls_config_view;
#endif

#ifdef LS_MAP_GLUE_IMPL
struct ls_map_def  g_ls_shapes[LS_MAP_MAX];
char               g_ls_names[LS_MAP_MAX][LS_MAP_NAME_MAX];
_Atomic uint32_t   g_ls_nshapes;             /* published with release ordering */
#else
extern struct ls_map_def g_ls_shapes[LS_MAP_MAX];
extern char              g_ls_names[LS_MAP_MAX][LS_MAP_NAME_MAX];
extern _Atomic uint32_t  g_ls_nshapes;
#endif

/* A pointer, mmap'd on first use --- NOT a __thread object. sizeof(struct
 * ls_map_set) is ~50 KB, and putting that in thread-local storage was both a
 * large TLS demand on every TMM thread and a direct contradiction of what this
 * file claims two paragraphs up ("mmap'd", because TMM's malloc is unusable on
 * threads it did not create). The claim was right; the code was not. */
#ifdef LS_MAP_GLUE_IMPL
__thread struct ls_map_set *g_ls_maps;
__thread int                g_ls_maps_failed;
/* WHICH SLOT IS EXECUTING, set by ls_vm_call before it enters the VM.
 *
 * uBPF's external_function_t is five uint64_t and NO context parameter --- ubpf.h warns
 * that a sixth will not match the typedef --- so a helper cannot be told which slot
 * invoked it. A thread-local is both simpler and cheaper than threading a context
 * through every call, and it is correct for the same reason the map tables are
 * per-thread: TMM is core-pinned and run-to-completion, so exactly one program is
 * executing on this thread at any instant.
 *
 * -1 when no program is running, so a helper reached from anywhere else refuses. */
__thread int                g_ls_cur_slot = -1;
#else
extern __thread struct ls_map_set *g_ls_maps;
extern __thread int                g_ls_maps_failed;
extern __thread int                g_ls_cur_slot;
#endif

/* Lazily bring this thread's storage up to the recorded shapes. Idempotent, and
 * checks the registry generation on each call. */
static inline struct ls_map_set *
ls_map_current(void)
{
    uint32_t n, i;
    uint64_t generation = atomic_load(&g_ls_map_registry.generation);
    void *p;

    if (g_ls_maps_failed)
        return 0;                     /* tried once, failed --- do not retry on
                                       * the hot path, and do not leak a mapping
                                       * per invocation */

    /* CATCH UP ON SHAPES ADDED SINCE THIS THREAD INITIALISED, and note why this
     * is not merely tidiness. Shapes are recorded at LOAD time and indices are
     * global; storage is built per thread on FIRST USE. So loading a second
     * program mid-life gives it a higher index than any thread has storage for,
     * and ls_map_get() returns NULL for it --- every lookup misses, and the
     * program behaves exactly like one whose counter never reaches its threshold.
     *
     * Observed: rate_watch worked at idx 0 on a fresh pod and silently never
     * worked at idx 1 after map_selftest had claimed idx 0. "Works on the first
     * program loaded, never on the second" is a bad failure to leave in place. */
    if (g_ls_maps != 0) {
        if (g_ls_maps->generation != generation) {
            memset(g_ls_maps, 0, sizeof *g_ls_maps);
            g_ls_maps->generation = generation;
        }
        n = atomic_load_explicit(&g_ls_nshapes, memory_order_acquire);
        for (i = g_ls_maps->n; i < n; i++) {
            if (ls_map_create(g_ls_maps, &g_ls_shapes[i]) < 0)
                return g_ls_maps;     /* table full --- existing maps still work */
        }
        return g_ls_maps;
    }

    /* ACQUIRE, paired with the release store in ls_map_reloc. Relocation runs on
     * the LOADER thread; without the pairing a data-plane thread on another core
     * has no guarantee of seeing either the count or the shapes it indexes, and
     * the failure is silent --- every lookup misses and the feature looks like a
     * map that is simply always empty. Same class as ls_vm_reload publishing vm
     * without jit_fn. */
    n = atomic_load_explicit(&g_ls_nshapes, memory_order_acquire);
    if (n == 0)
        return 0;                     /* no maps declared --- nothing to build */

    p = mmap(0, sizeof(struct ls_map_set), PROT_READ | PROT_WRITE,
             MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (p == MAP_FAILED) {
        g_ls_maps_failed = 1;
        return 0;
    }
    memset(p, 0, sizeof(struct ls_map_set));
    ((struct ls_map_set *)p)->generation = generation;

    for (i = 0; i < n; i++) {
        if (ls_map_create((struct ls_map_set *)p, &g_ls_shapes[i]) < 0) {
            munmap(p, sizeof(struct ls_map_set));
            g_ls_maps_failed = 1;     /* a shape we cannot honour --- fail safe */
            return 0;
        }
    }
    g_ls_maps = (struct ls_map_set *)p;
    return g_ls_maps;
}


/*
 * uBPF hands us the maps section and the symbol's offset within it. We read the
 * descriptor clang wrote there, check we can honour it, create the map, and
 * return the INDEX to plant in the instruction.
 *
 * Returning an index rather than a pointer is the security boundary: a program
 * never holds or supplies a host address, so validating a map reference later is
 * an integer range check and there is no forged-pointer case at all. Real BPF
 * hands programs an fd and does this work in the kernel; we get a stronger
 * arrangement for free because uBPF left relocation to the embedder.
 *
 * On refusal we return a deliberately out-of-range value. The helper's range
 * check then rejects it, so a descriptor we cannot honour yields a program whose
 * map calls all fail --- rather than one silently wired to the wrong shape, which
 * is what clamping would produce.
 */
static inline uint64_t
ls_map_reloc(void *ctx, const uint8_t *data, uint64_t data_size,
             const char *symbol_name, uint64_t symbol_offset, uint64_t symbol_size)
{
    struct ls_map_def d;
    int idx;

    if (data == 0)
        goto refused;
    if (symbol_offset > data_size || sizeof d > data_size - symbol_offset || symbol_size < sizeof d)
        goto refused;   /* truncated descriptor */

    memcpy(&d, data + symbol_offset, sizeof d);

    /* An unnamed map cannot be identified, and identity is what decides whether
     * storage is shared or private. Refuse rather than guess: a wrong guess in
     * either direction is silent. */
    if (symbol_name == 0 || symbol_name[0] == '\0')
        goto refused;
    if (strnlen(symbol_name, LS_MAP_NAME_MAX) >= LS_MAP_NAME_MAX)
        goto refused;   /* would not round-trip */

    /* ARRAY is currently the dedicated configuration view only. Its reference
     * identifies this loaded instance, not a name in the mutable hash registry.
     * A stale VM cannot use its reference to read its replacement's policy. */
    if (d.type == 2u || strcmp(symbol_name, LS_CONFIG_MAP_NAME) == 0) {
        uint64_t handle = (uint64_t)(uintptr_t)ctx;
        if (strcmp(symbol_name, LS_CONFIG_MAP_NAME) || d.type != 2u ||
            d.key_size != 4u || d.value_size != LS_CONFIG_VALUE_SIZE ||
            d.max_entries != LS_CONFIG_ROWS + 1u || d.map_flags != LS_CONFIG_MAP_FLAG ||
            !(handle & LS_CONFIG_HANDLE_BIT)) {
            g_ls_config.load_error = 1;
            goto refused;
        }
        return handle;
    }

    /* Already recorded under this NAME? clang emits one relocation per REFERENCE,
     * so the same map arrives several times --- three, in the experiment program.
     * Recording one shape per reference would exhaust the table and, worse, give
     * two references to the same declared map separate storage.
     *
     * A name match with a DIFFERENT shape is refused, not shared: the two
     * programs disagree about the layout of memory they would both write. */
    {
        uint32_t i, have = atomic_load_explicit(&g_ls_nshapes, memory_order_relaxed);
        for (i = 0; i < have; i++) {
            if (strncmp(g_ls_names[i], symbol_name, LS_MAP_NAME_MAX) != 0)
                continue;
            if (g_ls_shapes[i].type       == d.type &&
                g_ls_shapes[i].map_flags  == d.map_flags &&
                g_ls_shapes[i].key_size   == d.key_size &&
                g_ls_shapes[i].value_size == d.value_size &&
                g_ls_shapes[i].max_entries == d.max_entries)
                return (atomic_load(&g_ls_map_registry.generation) << 8) | i;
            fprintf(stderr, "ls_map: REFUSED %s --- shape disagrees with the "
                            "map already registered under that name "
                            "(have key=%u val=%u max=%u, asked key=%u val=%u max=%u)\n",
                    symbol_name,
                    g_ls_shapes[i].key_size, g_ls_shapes[i].value_size,
                    g_ls_shapes[i].max_entries,
                    d.key_size, d.value_size, d.max_entries);
            goto refused;
        }
    }

    /* Record the SHAPE only. Storage is per thread and built on first use --- see
     * ls_map_current(). Refuse here rather than at first use, so a descriptor we
     * cannot honour fails at load time where somebody is watching. */
    {
        uint32_t have = atomic_load_explicit(&g_ls_nshapes, memory_order_relaxed);
        if (!ls_map_check_descriptor(&d) || have >= LS_MAP_MAX) {
            g_ls_config.load_error = 1;
            goto refused;
        }
        idx = (int)have;
        g_ls_shapes[have] = d;
        /* Fill the shape AND THE NAME before publishing the count: a reader that
         * observes the count must be guaranteed to see the entry it indexes, and
         * the name is now part of that entry rather than a debug string. */
        memset(g_ls_names[have], 0, LS_MAP_NAME_MAX);
        memcpy(g_ls_names[have], symbol_name,
               strnlen(symbol_name, LS_MAP_NAME_MAX - 1u));
        atomic_store_explicit(&g_ls_nshapes, have + 1u, memory_order_release);
    }
    fprintf(stderr, "ls_map: reloc %s -> idx %d (key=%u val=%u max=%u)\n",
            symbol_name ? symbol_name : "?", idx,
            d.key_size, d.value_size, d.max_entries);
    return (atomic_load(&g_ls_map_registry.generation) << 8) | (uint64_t)idx;
refused:
    g_ls_config.load_error = 1;
    return (uint64_t)LS_MAP_MAX + 1u;
}

/* uBPF permits only the ctx and the stack. This extends it to map values --- and
 * note the JIT does not bounds-check at all, so without this the interpreter and
 * the JIT disagree: the program works in production and fails in test. */
/*
 * Release every recorded shape only when all slots are disabled and the
 * prepare path is idle. The loader checks those conditions before calling.
 *
 * Without this, shapes accumulate for the process lifetime: each load records
 * its own and LS_MAP_MAX is 4, so the fifth program loaded finds the table full
 * and its maps silently do not exist. Per-thread STORAGE is not reclaimed here
 * --- a data-plane thread may be inside a helper --- so the mapping is left and
 * the thread rebuilds from the new shapes on its next call. Bounded: it is one
 * mapping per thread, not per load.
 */
static inline int
ls_map_reset_shapes(void)
{
    if (atomic_exchange(&g_ls_map_registry.resetting, 1))
        return -1;
    uint64_t generation = atomic_load(&g_ls_map_registry.generation);
    if (atomic_load(&g_ls_map_registry.readers) || generation == ((1ull << 55) - 1)) {
        atomic_store(&g_ls_map_registry.resetting, 0);
        return -1; /* in-flight calls finish; generation exhaustion never wraps */
    }
    /* Clear the NAMES as well. They are identity now, so a name left behind at an
     * index the next load reuses would match a map it has nothing to do with ---
     * reintroducing exactly the cross-program aliasing the name key removes. */
    memset(g_ls_names, 0, sizeof g_ls_names);
    atomic_store_explicit(&g_ls_nshapes, 0, memory_order_release);
    atomic_store(&g_ls_map_registry.generation, generation + 1);
    atomic_store(&g_ls_map_registry.resetting, 0);
    return 0;
}

/* This runs on the thread doing the access, so ls_map_current() gives that
 * thread's own storage --- which is the only storage its program can legally
 * reach. */
static inline bool
ls_map_bounds(void *ctx, uint64_t addr, uint64_t size)
{
    (void)ctx;
    if (ls_config_addr_ok(&g_ls_config_view, addr, size))
        return true;
    struct ls_map_set *s = ls_map_current();
    return s != 0 && ls_map_addr_ok(s, addr, size) != 0;
}


/* --- the three helpers, at the ids PREVAIL already knows -----------------
 *
 * uBPF's external_function_t is FIVE uint64_t and NO context parameter --- ubpf.h
 * even warns that a 6th parameter will not match the typedef. There is a
 * dispatcher form that carries a context, but the map set is per-thread anyway,
 * so a thread-local pointer is both simpler and cheaper than threading a context
 * through every call.
 *
 * ls_map_set_current() is called once per thread when its maps are created. A
 * helper invoked on a thread that never did so finds NULL and returns failure ---
 * which is the safe direction: no map, no state, program falls through.
 */


static inline uint64_t
ls_h_map_lookup(uint64_t map, uint64_t key, uint64_t a, uint64_t b, uint64_t c)
{
    if (map & LS_CONFIG_HANDLE_BIT) {
        uint32_t index;
        if (!key) return 0;
        memcpy(&index, (const void *)(uintptr_t)key, sizeof index);
        return (uint64_t)(uintptr_t)ls_config_lookup(&g_ls_config, &g_ls_config_view,
                                                    map, index);
    }
    struct ls_map *m = ls_map_get(ls_map_current(), map);
    (void)a; (void)b; (void)c;
    if (m == 0 || key == 0)
        return 0;
    return (uint64_t)(uintptr_t)ls_map_lookup(m, (const uint8_t *)(uintptr_t)key);
}

static inline uint64_t
ls_h_map_update(uint64_t map, uint64_t key, uint64_t val, uint64_t flags, uint64_t c)
{
    if (map & LS_CONFIG_HANDLE_BIT) return (uint64_t)-1;
    struct ls_map *m = ls_map_get(ls_map_current(), map);
    (void)flags; (void)c;
    if (m == 0 || key == 0 || val == 0)
        return (uint64_t)-1;
    return (uint64_t)ls_map_update(m, (const uint8_t *)(uintptr_t)key,
                                   (const uint8_t *)(uintptr_t)val);
}

static inline uint64_t
ls_h_map_delete(uint64_t map, uint64_t key, uint64_t a, uint64_t b, uint64_t c)
{
    if (map & LS_CONFIG_HANDLE_BIT) return (uint64_t)-1;
    struct ls_map *m = ls_map_get(ls_map_current(), map);
    (void)a; (void)b; (void)c;
    if (m == 0 || key == 0)
        return (uint64_t)-1;
    return (uint64_t)ls_map_delete(m, (const uint8_t *)(uintptr_t)key);
}

/* --- readable-range cache, for bpf_probe_read ----------------------------
 *
 * WHY A RANGE CHECK AND NOT A FAULT HANDLER. bpf_probe_read must return an ERROR for a bad
 * address, never crash. The kernel gets that from its page-fault handler plus a fixup
 * table. Userspace has three options and only one of them is affordable on a poll loop:
 *
 *   range-check against cached mappings   two compares. Catches NULL, wild pointers and
 *                                         unmapped addresses --- the whole common case.
 *   process_vm_readv on self              a syscall per read. Catches everything, and is
 *                                         far too slow per invocation.
 *   SIGSEGV handler + siglongjmp          catches everything, but async-signal-safety
 *                                         inside run-to-completion, and the handler is
 *                                         PROCESS-WIDE so it collides with TMM's own crash
 *                                         handling. Not a trade to make quietly.
 *
 * So: range check. STATE THE LIMIT PLAINLY --- it does not catch a pointer that is mapped
 * but wrong. Neither does a hand-written ctx builder, which dereferences on trust today, so
 * this is not a regression; it is a bound where there was none.
 *
 * PER THREAD, like the map storage, for the same reason: no locking on the hot path. Built
 * on first use from /proc/self/maps, and REFRESHED ONCE on a miss before refusing, because
 * TMM mmaps after init (the per-thread map tables are themselves an example) and a stale
 * snapshot would refuse a legitimate read forever.
 */
#define LS_RANGES_MAX 64u

struct ls_range { uint64_t lo, hi; };

struct ls_ranges {
    struct ls_range r[LS_RANGES_MAX];
    uint32_t n;
};

#ifdef LS_MAP_GLUE_IMPL
__thread struct ls_ranges *g_ls_ranges;
__thread int               g_ls_ranges_failed;
#else
extern __thread struct ls_ranges *g_ls_ranges;
extern __thread int               g_ls_ranges_failed;
#endif

/* Parse /proc/self/maps into the readable ranges.
 *
 * Deliberately ignores any mapping without 'r' --- a write-only or guard mapping is not
 * somewhere a program may read from. Uses stdio because this runs ONCE PER THREAD at first
 * use, off the hot path; the per-invocation cost is the two compares in ls_addr_readable.
 */
static inline int
ls_ranges_load(struct ls_ranges *rs)
{
    FILE *f;
    char line[512];

    rs->n = 0;
    f = fopen("/proc/self/maps", "r");
    if (f == 0)
        return -1;
    while (rs->n < LS_RANGES_MAX && fgets(line, (int)sizeof line, f) != 0) {
        char *p = line, *q;
        uint64_t lo, hi;

        lo = strtoull(p, &q, 16);
        if (q == p || *q != '-')
            continue;
        p = q + 1;
        hi = strtoull(p, &q, 16);
        if (q == p || hi <= lo)
            continue;
        while (*q == ' ')
            q++;
        if (*q != 'r')                 /* not readable --- not our business */
            continue;
        /* Merge with the previous range when they abut. /proc/self/maps splits on permission
         * and backing changes, so a heap can appear as several adjacent readable entries and
         * a 64-slot table would otherwise fill on a large process. */
        if (rs->n > 0 && rs->r[rs->n - 1].hi == lo) {
            rs->r[rs->n - 1].hi = hi;
        } else {
            rs->r[rs->n].lo = lo;
            rs->r[rs->n].hi = hi;
            rs->n++;
        }
    }
    fclose(f);
    return rs->n ? 0 : -1;
}

/* This thread's ranges, built on first use. Returns 0 on failure, and remembers the
 * failure so a broken /proc is not retried on every invocation. */
static inline struct ls_ranges *
ls_ranges_current(int refresh)
{
    if (g_ls_ranges_failed && !refresh)
        return 0;
    if (g_ls_ranges == 0) {
        void *m = mmap(0, sizeof(struct ls_ranges), PROT_READ | PROT_WRITE,
                       MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (m == MAP_FAILED) {
            g_ls_ranges_failed = 1;
            return 0;
        }
        g_ls_ranges = (struct ls_ranges *)m;
        refresh = 1;
    }
    if (refresh) {
        if (ls_ranges_load(g_ls_ranges) != 0) {
            g_ls_ranges_failed = 1;
            return 0;
        }
        g_ls_ranges_failed = 0;
    }
    return g_ls_ranges;
}

/* Is [addr, addr+size) entirely inside ONE readable mapping?
 *
 * One mapping, not several: a read spanning two adjacent mappings is legal in principle and
 * is far more likely to be a pointer that walked off the end of something. Refusing it costs
 * a caller nothing real and removes a whole class of accident.
 *
 * On a miss the snapshot is REFRESHED ONCE and retried, because TMM mmaps after init --- the
 * per-thread map tables are themselves an example --- and a stale snapshot would refuse a
 * legitimate read forever.
 */
static inline int
ls_addr_readable(uint64_t addr, uint64_t size)
{
    int attempt;

    if (size == 0 || addr == 0)
        return 0;
    if (addr + size < addr)                 /* wrap --- refuse before doing arithmetic */
        return 0;

    for (attempt = 0; attempt < 2; attempt++) {
        struct ls_ranges *rs = ls_ranges_current(attempt);   /* 2nd pass refreshes */
        uint32_t i;
        if (rs == 0)
            return 0;
        for (i = 0; i < rs->n; i++) {
            if (addr >= rs->r[i].lo && addr + size <= rs->r[i].hi)
                return 1;
        }
    }
    return 0;
}

/* --- bpf_ktime_get_ns, helper id 5 ---------------------------------------
 *
 * WHY A CLOCK IS THE SINGLE MOST USEFUL ADDITION. Without one a program cannot know what
 * time it is, so it cannot express "N per second", any rate limit, or any decay. That is
 * why rate_watch's threshold means "this site fired more than 5 times EVER" rather than
 * recently --- the counter never resets, so safe_returns answers a question nobody asked.
 *
 * CLOCK_MONOTONIC, NOT CLOCK_REALTIME, and the difference matters. The ring record's
 * ts_ns is REALTIME because a feed has to correlate with wall-clock logs. A program doing
 * rate limiting must NOT be affected by a clock step: on a REALTIME jump backwards every
 * interval computation would go negative and every limiter would open. Two clocks for two
 * jobs, deliberately, and a program comparing its own timestamps against a record's ts_ns
 * would be comparing different clocks --- which is why programs get no access to ts_ns.
 *
 * Resolves through the vDSO, so no syscall. It is still a read on the hot path and the
 * per-call cost of it is UNMEASURED, like everything else on this path.
 */
static inline uint64_t
ls_h_ktime_get_ns(uint64_t a, uint64_t b, uint64_t c, uint64_t d, uint64_t e)
{
    struct timespec ts;
    (void)a; (void)b; (void)c; (void)d; (void)e;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
        return 0;      /* 0 is safe: a program comparing against it sees no elapsed time */
    return (uint64_t)ts.tv_sec * 1000000000ull + (uint64_t)ts.tv_nsec;
}

/* --- bpf_ringbuf_output, helper id 130 -----------------------------------
 *
 * PROGRAM-CONTROLLED EMISSION. Until now the host published a record for every event,
 * after the program ran, so a program could not say "this one is not interesting". That
 * fixed one-record-per-event rate is what the parked timer hook existed to work around;
 * with this helper and a clock, a program does its own rate limiting and its own
 * summarising, and the timer is not needed.
 *
 * Signature is bpf_ringbuf_output(ringbuf, data, size, flags) --- id 130, which PREVAIL
 * already knows, so this costs ZERO verifier work. Verified by test 2026-08-18: a program
 * declaring a BPF_MAP_TYPE_RINGBUF map and calling id 130 passes PREVAIL unchanged.
 *
 * WHAT WE VALIDATE, AND WHAT WE CANNOT. `size` is clamped and refused above the cap. The
 * POINTER is trusted, because PREVAIL proved the program owns [data, data+size) --- and
 * that is precisely the trust uBPF's own docs/VerifiedPrograms.md warns about: "PREVAIL
 * assumes that r1 points to a valid memory region" while uBPF "doesn't enforce any
 * particular context layout" and "memory safety depends on the program". The interpreter
 * would catch a bad pointer through the bounds callback; THE JIT DOES NOT CONSULT IT, and
 * the lab runs the JIT. So the real control here is signature verification of the program
 * (scope item 4, unbuilt), not this function. Stated rather than implied.
 */
#define LS_RB_MAX_RECORD 256u   /* the drain reads into a 512-byte buffer; stay well
                                 * under it, and cap what one program can push per
                                 * invocation so a hot hook cannot flood the ring in a
                                 * single call */

static inline uint64_t
ls_h_perf_event_output(uint64_t ctx, uint64_t map, uint64_t flags, uint64_t data,
                       uint64_t size)
{
    struct ls_map *m = ls_map_get(ls_map_current(), map);

    /* ARGUMENT ORDER IS bpf_perf_event_output(ctx, map, flags, data, size). The map is
     * arg 1 and the payload is args 3 and 4 --- NOT bpf_ringbuf_output's
     * (map, data, size, flags), which this used before id 130 turned out to be outside
     * uBPF's table. Getting the order wrong would read the ctx pointer as a map index. */
    (void)ctx; (void)flags;

    /* Refuse, never clamp. A silently truncated record decodes as a short one and a
     * consumer cannot tell it from a program that meant to emit that much. */
    if (m == 0 || !m->is_ring)
        return (uint64_t)-1;          /* not an event-output map */
    if (data == 0 || size == 0 || size > LS_RB_MAX_RECORD)
        return (uint64_t)-1;
    if (g_ls_cur_slot < 0)
        return (uint64_t)-1;          /* reached from outside a program run */

    return (uint64_t)(int64_t)ls_tp_publish_raw(g_ls_cur_slot,
                                                (const void *)(uintptr_t)data,
                                                (unsigned long)size);
}

/* --- bpf_probe_read, helper id 4 -----------------------------------------
 *
 * WHY THIS IS THE MOST STRUCTURALLY IMPORTANT HELPER IN THE SET. A verified program cannot
 * chase a pointer --- PREVAIL refuses it --- so until now the HOST had to dereference and
 * hand the program flat scalars. That host code is a per-hook ctx builder written in C and
 * COMPILED INTO TMM, which means a hook with a new argument shape costs a rebuild.
 *
 * With this helper the program chases pointers itself, and the generic five-register ctx
 * covers arbitrary hooks. A new hook shape becomes a NEW PROGRAM rather than a new build:
 * minutes instead of a build cycle. That is the difference between "we can instrument
 * anything, given a rebuild" and "we can instrument anything, now".
 *
 * PREVAIL admits id 4 with every gate on --- verified before this was written, not after.
 *
 * WHAT IS AND IS NOT GUARANTEED, stated because the whole value depends on it:
 *
 *   src   RANGE-CHECKED against this thread's readable mappings. NULL, unmapped and wild
 *         pointers are refused with -1 rather than faulting. A pointer that is mapped but
 *         semantically wrong is NOT caught --- and neither is it by a hand-written ctx
 *         builder, which dereferences on trust today. This is a bound where there was none.
 *   size  capped. A program cannot ask for an unbounded copy.
 *   dst   TRUSTED, because PREVAIL proved the program owns it. Same trust the event-output
 *         helper takes, and the same reason it is the signing gate (scope item 4) that
 *         really underwrites this rather than any check here.
 *
 * The kernel's version of this helper is backed by the page-fault handler and a fixup table.
 * Ours is a range check, because the userspace alternatives are a syscall per read (far too
 * slow on a poll loop) or a process-wide SIGSEGV handler with siglongjmp (async-signal-safety
 * inside run-to-completion, colliding with TMM's own crash handling). The range check is the
 * affordable 95%, and saying which 5% it misses is the point of this comment.
 */
#define LS_PROBE_READ_MAX 256u

static inline uint64_t
ls_h_probe_read(uint64_t dst, uint64_t size, uint64_t src, uint64_t d, uint64_t e)
{
    (void)d; (void)e;

    if (dst == 0 || src == 0 || size == 0)
        return (uint64_t)-1;
    if (size > LS_PROBE_READ_MAX)
        return (uint64_t)-1;          /* refuse, never clamp --- a short read is
                                       * indistinguishable from a program that meant it */
    if (!ls_addr_readable(src, size))
        return (uint64_t)-1;

    memcpy((void *)(uintptr_t)dst, (const void *)(uintptr_t)src, (size_t)size);
    return 0;
}

/* Assert the helper signatures really match uBPF's, so a future edit that adds a
 * parameter fails the build rather than corrupting arguments at run time. */
static inline void
ls_map_glue_abi_check(void)
{
    external_function_t f;
    f = (external_function_t)ls_h_map_lookup; (void)f;
    f = (external_function_t)ls_h_map_update; (void)f;
    f = (external_function_t)ls_h_map_delete; (void)f;
    f = (external_function_t)ls_h_ktime_get_ns; (void)f;
    f = (external_function_t)ls_h_perf_event_output; (void)f;
    f = (external_function_t)ls_h_probe_read; (void)f;
}

/*
 * THE ONE CALL. Every VM that will run a program with maps goes through here,
 * before ubpf_load_elf_ex --- see the ordering note in the banner. Returns 0, or
 * -1 with a reason on stderr.
 *
 * Registration is all-or-nothing on purpose. A VM with the relocation callback
 * but no bounds check would resolve map indices and then refuse every read of a
 * value; a VM with helpers but no relocation would hand every helper map=0. Both
 * produce a program that loads, verifies and runs while its maps do nothing. So a
 * partial install is treated as a failed install.
 */
static inline int
ls_map_glue_install(struct ubpf_vm *vm)
{
    if (vm == 0)
        return -1;

    /* Order: relocation first, because ubpf_load_elf_ex walks the maps section
     * and consults it there. Registered afterwards it is simply never asked. */
    g_ls_config.load_error = 0;
    if (ubpf_register_data_relocation(vm, (void *)(uintptr_t)g_ls_config.loading,
                                      ls_map_reloc) != 0) {
        fprintf(stderr, "ls_map: relocation callback refused\n");
        return -1;
    }
    if (ubpf_register_data_bounds_check(vm, 0, ls_map_bounds) != 0) {
        fprintf(stderr, "ls_map: bounds callback refused\n");
        return -1;
    }

    /* ids 1/2/3 with the standard names and semantics, which is what lets
     * PREVAIL verify these programs with no platform work at all. */
    if (ubpf_register(vm, 1, "bpf_map_lookup_elem",
                      (external_function_t)ls_h_map_lookup) != 0 ||
        ubpf_register(vm, 2, "bpf_map_update_elem",
                      (external_function_t)ls_h_map_update) != 0 ||
        ubpf_register(vm, 3, "bpf_map_delete_elem",
                      (external_function_t)ls_h_map_delete) != 0) {
        fprintf(stderr, "ls_map: helper registration refused\n");
        return -1;
    }

    /* ids 5 and 130, again with the standard names and semantics so PREVAIL needs no
     * platform work. All-or-nothing with the three above: a VM that resolved a ringbuf
     * map and then had no helper to emit through would give a program that verifies,
     * runs, and silently drops everything it tried to publish. */
    /* EVERY ID MUST BE INSIDE uBPF'S TABLE, asserted at COMPILE time. ubpf_register
     * refuses idx >= UBPF_MAX_EXT_FUNCS (64 by default, ubpf.h:72) and returns -1, which
     * all-or-nothing turns into a total install failure. An image shipped that way on
     * 2026-08-18: bpf_ringbuf_output's id is 130, so NO helper registered at all, every
     * program load was refused and even the built-in shield never armed. Loud, which is
     * what all-or-nothing is for --- but a build failure is better than loud. */
    _Static_assert(4  < UBPF_MAX_EXT_FUNCS, "bpf_probe_read id outside uBPF's table");
    _Static_assert(5  < UBPF_MAX_EXT_FUNCS, "bpf_ktime_get_ns id outside uBPF's table");
    _Static_assert(25 < UBPF_MAX_EXT_FUNCS, "bpf_perf_event_output id outside the table");
    _Static_assert(1  < UBPF_MAX_EXT_FUNCS && 2 < UBPF_MAX_EXT_FUNCS
                   && 3 < UBPF_MAX_EXT_FUNCS, "map helper ids outside uBPF's table");

    if (ubpf_register(vm, 4, "bpf_probe_read",
                      (external_function_t)ls_h_probe_read) != 0 ||
        ubpf_register(vm, 5, "bpf_ktime_get_ns",
                      (external_function_t)ls_h_ktime_get_ns) != 0 ||
        ubpf_register(vm, 25, "bpf_perf_event_output",
                      (external_function_t)ls_h_perf_event_output) != 0) {
        fprintf(stderr, "ls_map: probe-read/clock/event-output registration refused\n");
        return -1;
    }

    ls_map_glue_abi_check();     /* compile-time signature pin, no run cost */
    return 0;
}

#endif /* LS_MAP_GLUE_H */

exit_admit.py.text:
#!/usr/bin/env python3
"""exit_admit.py --- the admission gate for a function-EXIT (fexit) hook.

Arming an exit hook does two things an entry hook does not: it READS the return
value, and it HIJACKS the return address. Each imposes a requirement on the target
function, and both are checkable offline from the build's own binary --- so they
are gates, not hopes. This tool answers, for one function on one build:

  #5  Is the return type rax-representable?  The exit stub captures rax(:rdx). A
      float/double is returned in xmm0, and a by-value struct via a hidden pointer
      (or in memory) --- in neither case is rax "the value", so a program reading
      c->ret would get garbage. Admit only integer/enum/pointer/bool returns
      (rdx:rax for a <=16-byte integer pair). Refuse float, by-value struct/union,
      and void (nothing to read).

  #4  Can a non-local exit unwind THROUGH the frame?  The return-address hijack
      corrupts a stack unwind that walks the frame. TMM initiates no unwind ---
      P8, verified on the build box: zero _Unwind_* / __cxa_* imports --- so no TMM
      frame can sit on a completed throw->catch chain. This RE-CHECKS that property
      against the actual runtime binary. If it ever fails (TMM gains C++ exception
      handling), exit hooks are refused wholesale, because the empty-exclusion-set
      argument no longer holds and a real per-target reachability analysis is owed.

Usage:
    exit_admit.py <debug-binary> <runtime-binary> <function>

Exit status: 0 = ADMIT, 1 = REFUSE (reasons on stderr), 2 = could not decide
(missing tool / symbol) --- which is also a refusal, because an exit hook admitted
on an undecided target is exactly the failure this gate exists to prevent.
"""
import re
import subprocess
import sys

UNWIND_INITIATORS = (
    "_Unwind_RaiseException", "_Unwind_ForcedUnwind", "_Unwind_Resume",
    "__cxa_throw", "__cxa_begin_catch", "__cxa_rethrow",
)

DWARFDUMP = ("llvm-dwarfdump", "/usr/lib/llvm-18/bin/llvm-dwarfdump", "llvm-dwarfdump-18")


class _Miss:
    returncode = 127
    stdout = ""
    stderr = ""


def sh(*argv):
    """Run a command; a missing executable is a non-zero result, not an exception."""
    try:
        return subprocess.run(argv, capture_output=True, text=True)
    except (FileNotFoundError, OSError):
        return _Miss()


def which_dwarfdump():
    for d in DWARFDUMP:
        if sh(d, "--version").returncode == 0:
            return d
    return None


def func_addr(debug_bin, fn):
    """The function's load address, from the (unstripped) debug companion's symtab."""
    r = sh("nm", debug_bin)
    for line in r.stdout.splitlines():
        p = line.split()
        if len(p) == 3 and p[2] == fn and p[1] in ("T", "t", "W", "w"):
            try:
                return int(p[0], 16)
            except ValueError:
                return None
    return None


def frame_has_lsda(runtime_bin, addr):
    """(has_lsda, decided) --- does the .eh_frame FDE covering `addr` carry a C++
    exception LSDA (a cleanup/landing-pad site the unwinder would process)? An
    unwind through such a frame is exactly what the return-address hijack corrupts.
    Only a handful of frames have one (the C++ TUs); a plain C data-path function
    does not. `decided` is False if the tool is unavailable."""
    dd = which_dwarfdump()
    if dd is None or addr is None:
        return (False, False)
    r = sh(dd, "--eh-frame", runtime_bin)
    lo = hi = None
    cur_lsda = False
    fde = re.compile(r"FDE .*pc=([0-9a-f]+)\.\.\.([0-9a-f]+)")
    for line in r.stdout.splitlines():
        m = fde.search(line)
        if m:
            if lo is not None and lo <= addr < hi:
                return (cur_lsda, True)          # the FDE that covers addr closed
            lo, hi = int(m.group(1), 16), int(m.group(2), 16)
            cur_lsda = False
        elif "LSDA Address" in line:
            cur_lsda = True
    if lo is not None and lo <= addr < hi:
        return (cur_lsda, True)
    return (False, True)   # no FDE covers addr -> no unwind info -> nothing to traverse


def return_type(debug_bin, fn):
    """The function's declared return type, via the build's DWARF. Returns the
    type string, or None if gdb or the symbol is unavailable."""
    r = sh("gdb", "-q", "-batch", "-ex", "ptype %s" % fn, debug_bin)
    for line in r.stdout.splitlines():
        line = line.strip()
        if not line.startswith("type = "):
            continue
        body = line[len("type = "):]
        # "type = <ret> (<params>)"  --- the parameter list is the LAST top-level
        # "(...)"; everything before it is the return type. enum {...} and struct
        # names carry no parens, so rsplit on the last " (" is safe here.
        if " (" in body:
            body = body.rsplit(" (", 1)[0]
        return body.strip()
    return None


def classify_return(t):
    """(safe: bool, reason: str) for a return-type string."""
    if t is None:
        return False, "return type could not be read from DWARF"
    ts = t.strip()
    if ts.endswith("*"):
        return True, "pointer (in rax)"
    if ts == "void":
        return False, "void return --- there is no value for the exit program to read"
    if ts.startswith(("float", "double", "long double", "_Float", "__float")):
        return False, "floating-point return (xmm0, NOT rax) --- c->ret would be garbage"
    if ts.startswith(("struct ", "union ", "class ")):
        return False, ("by-value %s return (hidden pointer / memory, NOT the value) --- "
                       "refused conservatively" % ts.split()[0])
    # integer family, enums, bool
    if ts.startswith(("enum", "int", "unsigned", "char", "short", "long",
                      "signed", "_Bool", "bool", "uint", "u_int", "size_t",
                      "ssize_t", "int8", "int16", "int32", "int64",
                      "uint8", "uint16", "uint32", "uint64")):
        return True, "%s (rax)" % (ts if len(ts) < 40 else ts[:37] + "...")
    return False, "unrecognised return type %r --- refused conservatively" % ts


def unwind_clear(runtime_bin):
    """(clear: bool, found: list) --- P8: the binary must import no unwind
    initiator. Reads .dynsym for UND symbols."""
    r = sh("readelf", "--dyn-syms", runtime_bin)
    found = []
    for line in r.stdout.splitlines():
        if " UND " not in line:
            continue
        for s in UNWIND_INITIATORS:
            # match the bare symbol (may carry an @GLIBC version suffix)
            if re.search(r"\b%s\b" % re.escape(s), line):
                found.append(s)
    return (len(found) == 0), sorted(set(found))


def main(argv):
    if len(argv) != 4:
        sys.stderr.write(__doc__)
        return 2
    debug_bin, runtime_bin, fn = argv[1], argv[2], argv[3]

    rt = return_type(debug_bin, fn)
    safe_ret, why_ret = classify_return(rt)

    clear, found = unwind_clear(runtime_bin)                       # #4a binary-wide (P8)
    addr = func_addr(debug_bin, fn)
    lsda, lsda_decided = frame_has_lsda(runtime_bin, addr)         # #4b per-target

    print("exit-admit: %s" % fn)
    print("  #5 return type : %s --- %s" % (rt if rt else "?", why_ret))
    if clear:
        print("  #4a unwind     : clear --- TMM imports no unwind initiator (P8 holds)")
    else:
        print("  #4a unwind     : VIOLATED --- binary imports %s" % ", ".join(found))
    if not lsda_decided:
        print("  #4b frame      : UNCHECKED --- no llvm-dwarfdump; per-target LSDA not verified")
    elif lsda:
        print("  #4b frame      : has a C++ exception LSDA --- an unwind would process this frame")
    else:
        print("  #4b frame      : no LSDA --- plain frame, nothing for an unwind to process here")

    safe_unwind = clear and not lsda
    ok = safe_ret and safe_unwind
    if ok:
        print("  VERDICT        : ADMIT")
        return 0

    if not safe_ret:
        sys.stderr.write("*** REFUSE %s: %s\n" % (fn, why_ret))
    if not clear:
        sys.stderr.write("*** REFUSE %s: TMM now initiates unwinds (%s); the empty-exclusion-set\n"
                         "    argument (P8) no longer holds. A per-target unwind-reachability\n"
                         "    analysis is owed before any exit hook is admitted.\n"
                         % ", ".join(found))
    if lsda:
        sys.stderr.write("*** REFUSE %s: the target frame carries a C++ exception landing pad\n"
                         "    (LSDA); a stack unwind would process it, and the return-address\n"
                         "    hijack corrupts an unwind that walks the frame.\n" % fn)
    print("  VERDICT        : REFUSE")
    return 1


if __name__ == "__main__":
    sys.exit(main(sys.argv))
